import { ELIGIBILITY_DIMENSIONS, ELIGIBILITY_FIELDS, JSON_LOGIC_OPERATORS, LAUNCH_DIMENSIONS } from "../../shared/contracts/eligibility";
import { DIMENSION_LABELS, ENGINE_VERSION, REASON_TEMPLATES, SELF_CHECK_TEMPLATES } from "../../shared/eligibility/index";
import { MAX_TEXT } from "../../shared/eligibility/reasons";
import { CLASS_YEARS, CLASS_YEAR_INDEX, GPA_BAND_BOUNDS, MAJOR_FAMILIES, MAJOR_FAMILY_CIP_SERIES } from "../../shared/taxonomy";
import { goldenSnapshot } from "./golden-runner";

/**
 * Generated files the Python port (pipeline/novus_eligibility) reads, so it never re-types a
 * TypeScript table by hand:
 *
 * - data/catalogue.json: the field catalogue, dimensions, class years, GPA band edges, CIP
 *   series and reason copy the evaluator needs;
 * - data/node-results.json: the Node (server-safe) result for every golden case, which the Python
 *   runner and the workerd project compare against in full.
 *
 * infra/eligibility/eligibility.test.ts fails when either file is stale; regenerate with
 *   UPDATE_GOLDEN=1 npx vitest run --config infra/vitest.config.ts infra/eligibility
 */

export const PYTHON_DATA_DIR = "pipeline/novus_eligibility/data";

export function pythonCatalogue(): unknown {
  return {
    $comment: "Generated from shared/ by infra/eligibility/snapshots.ts; do not edit by hand.",
    engineVersion: ENGINE_VERSION,
    dimensions: ELIGIBILITY_DIMENSIONS,
    launchDimensions: LAUNCH_DIMENSIONS,
    operators: JSON_LOGIC_OPERATORS,
    fields: ELIGIBILITY_FIELDS,
    classYears: CLASS_YEARS,
    classYearIndex: CLASS_YEAR_INDEX,
    gpaBandBounds: GPA_BAND_BOUNDS,
    majorFamilies: MAJOR_FAMILIES,
    majorFamilyCipSeries: MAJOR_FAMILY_CIP_SERIES,
    reasons: REASON_TEMPLATES,
    selfCheck: SELF_CHECK_TEMPLATES,
    dimensionLabels: DIMENSION_LABELS,
    maxText: MAX_TEXT,
  };
}

export function nodeResultsFile(input: { cases: unknown; ruleSets: unknown }): unknown {
  return {
    $comment:
      "Generated by infra/eligibility/snapshots.ts: the server-safe Node result for every golden case (sample data; no device answers are ever used). Python and workerd must match it exactly.",
    engineVersion: ENGINE_VERSION,
    sample: true,
    results: goldenSnapshot(input),
  };
}

/** The text a generated file must contain (two-space JSON plus a trailing newline). */
export function jsonText(value: unknown): string {
  return `${JSON.stringify(value, null, 2)}\n`;
}
